<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.parser </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> PydanticOutputParser</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">pydantic_object</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">JudgeVerdict)</span></span>
